  const head = (kick, h, p) => `<section class="sec hero-in" style="padding-bottom:30px"><div class="wrap"><div class="kick">${kick}</div><h1 class="h1">${h}</h1>${p ? `<p class="lede">${p}</p>` : ""}</div></section>`;
  const portal = mod => `<section style="padding:0 0 40px"><div class="wrap" style="max-width:1320px"><div class="rise">${APP.hub(mod)}</div><p class="src">A working mock with sample houses, builders and numbers. Click around: every item in the menu opens.</p></div></section>`;
  const icard = c => `<div class="card"><span class="mi" style="width:40px;height:40px;border-radius:11px;background:rgba(224,122,46,.15);color:#f2a865;display:grid;place-items:center;margin-bottom:12px">${svgI(c[0], 22)}</span><b style="font-size:20px;display:block">${c[1]}</b><p class="mute" style="margin:8px 0 0;font-size:16px">${c[2]}</p></div>`;
  const cards = (h, list) => `<section class="sec" style="padding-top:30px"><div class="wrap">${h ? `<h2 class="h2 rise" style="margin-bottom:26px">${h}</h2>` : ""}<div class="grid g3 rise">${list.map(icard).join("")}</div></div></section>`;
  const tbl = (hd, rows) => `<div class="tblwrap rise" style="margin-top:24px"><table class="tbl"><tr>${hd.map(h => `<th>${h}</th>`).join("")}</tr>${rows.map(r => `<tr>${r.map((c, i) => `<td${i === 0 ? " style='font-weight:700'" : ""}>${c}</td>`).join("")}</tr>`).join("")}</table></div>`;
  const bad = t => `<b style='color:var(--bad)'>${t}</b>`;

  /* ---------- the deep read ---------- */
  APP.views.read = () => head("Where you stand", "The deep read.", "We looked at everything public about Original Mechanical: the license, the company record, the website and its code, every listing, the ads, the search results and the competition. Every fact here has its source.")
    + `<section class="sec" style="padding-top:20px"><div class="wrap">
      <div class="grid g4 keep2 rise">${[["CR-39", "ROC #350004, dual license, first issued Feb 2024, active to Feb 2028"], ["0", "complaints on the license. A clean record"], ["0", "public reviews, on Google, Yelp, BBB, Houzz, Angi or anywhere else we looked"], ["$0", "on Google or Meta ads. No ads point at your site"]].map(s => `<div class="stat"><b style="font-size:38px">${s[0]}</b><span>${s[1]}</span></div>`).join("")}</div>
      <p class="src">Sources: ${src("Arizona ROC contractor search", "https://azroc.my.site.com/AZRoc/s/contractor-search")} · ${src("Google Ads Transparency Center", "https://adstransparency.google.com/")} · ${src("Meta Ad Library", "https://www.facebook.com/ads/library/")} · live searches, Nov 8, 2026. research/company-and-listings.md</p>
    </div></section>
    <section class="sec"><div class="wrap split">
      <div class="rise"><div class="kick">The website</div><h2 class="h2">Good bones. Leftover parts.</h2><ul class="lst"><li>Rebuilt in April 2026 on WordPress and Elementor, likely by an outside designer</li><li>Every page's title says <b>"Custom Home Builders & High-End Remodel Contractors"</b>, and that's how Google shows it</li><li>The contact page reads "HVAC Services in, AZ": the city was never filled in</li><li>The template's "Hello world!" post is still live</li><li>No license number, no address, no reviews, no way to send plans</li><li>The form's phone field is coded as "email", so a lead's number can land in the wrong place</li><li>No analytics at all: nobody can tell what the site brings in</li><li>The logo alone is 862 KB on every page</li></ul></div>
      <div class="rise card" style="padding:0;overflow:hidden"><img src="img/work/IMG_5187.jpg?v=1794181557" alt="A great room with clerestory windows and linear slot diffusers" style="aspect-ratio:4/3;object-fit:cover;width:100%"></div>
    </div><div class="wrap"><p class="src">The site's HTML, its sitemap and Wayback Machine snapshots, Nov 8, 2026. research/tech-seo-competitors.md</p></div></section>
    <section class="sec"><div class="wrap"><div class="kick">Your listings</div><h2 class="h2 rise">Nowhere to leave a review.</h2>
      ${tbl(["Where", "What's there", "Reviews"], [["Your site", "Says 15+ years, 500+ systems and a 5★ average", "none shown, no link to any"], ["Google Business Profile", bad("none came up, even searching your name"), "0"], ["Instagram @ogmechanicalco", "78 followers, 0 posts, not linked from the site", "n/a"], ["Yelp, BBB, Angi, Houzz, Nextdoor", bad("not found"), "0"], ["BuildZoom", "An unclaimed profile made from your license", "0"], ["SRP contractor list", "Not confirmed. We'll ask", "n/a"]])}
      <p class="src">The 15+ years, 500+ systems and 5★ may all be true of your career. Online, nothing backs them yet: the LLC is from January 2024, and there's no review to point to. The fix isn't to drop the numbers. It's to prove them, with captioned projects, builder names and reviews.</p></div></section>
    <section class="sec"><div class="wrap split">
      <div class="rise"><div class="kick">Search</div><h2 class="h2">Found where it counts. Missing everywhere else.</h2><p class="lede">Your Scottsdale page came up #1 for "custom home HVAC Scottsdale" on one search and about #8 a few minutes later. That's the right search to win. But for anything a homeowner types when the AC quits, and for your own town, you don't show up at all.</p></div>
      <div class="rise">${tbl(["Someone searches", "You show?"], [["custom home HVAC Scottsdale", `<span class="tag ok">#1 to #8</span>`], ["HVAC contractor custom homes Phoenix", `<span class="tag bad">No</span>`], ["luxury home HVAC Arizona", `<span class="tag bad">No</span>`], ["HVAC Mesa AZ", `<span class="tag bad">No</span>`], ["AC repair Mesa", `<span class="tag bad">No</span>`]])}<p class="src">Google searches, Nov 8, 2026, from outside Arizona, so local results will differ a little.</p></div>
    </div></section>
    <section class="sec"><div class="wrap"><div class="kick">Who shows up instead</div><h2 class="h2 rise">The competition has a head start, not better work.</h2>
      ${tbl(["Company", "Where", "What they lead with", "Google reviews"], [["K&M Air", "Mesa", "A \"Luxury Custom Home HVAC\" page. Owns \"luxury home HVAC Arizona\"", "not captured"], ["Hicken Air", "Gilbert", "HVAC layout and installs for new builds and custom homes", "4.7 · 452"], ["Expert HVAC Services", "Glendale", "New custom homes, custom ductwork, zoning", "4.9 · 519"], ["Comfort One", "Scottsdale", "A project portfolio page, 400+ reviews", "5.0 · 582"], ["Forbes Refrigeration", "Scottsdale", "Wine rooms and zoned luxury homes, 40+ years", "4.9 · 76"], ["Larson Air", "Scottsdale", "Service, and 59 Google ads running", "4.9 · 2K"]])}
      <p class="src">Nearly all of them book online (ServiceTitan or Housecall Pro), offer financing (Wells Fargo, Synchrony, GreenSky, Service Finance, GoodLeap) and track their calls. Original Mechanical has none of that layer yet. research/tech-seo-competitors.md</p></div></section>
    <section class="sec"><div class="wrap"><div class="kick">Two smaller things</div>
      <div class="grid g2 rise" style="margin-top:20px">
        <div class="card"><b style="font-size:20px">"Quality Air Solutions" is taken</b><p class="mute" style="font-size:16px">Two unrelated Arizona contractors already use the name, one of them a Chandler business in the same East Valley market. Keep it on the patch, but build the brand on "Original".</p><p class="src">Arizona ROC search · research/company-and-listings.md</p></div>
        <div class="card"><b style="font-size:20px">Three names for one company</b><p class="mute" style="font-size:16px">Original Mechanical LLC, Original Mechanical Co. and Original Mechanical Company all appear. Pick one for the public, use it everywhere, and keep the LLC for contracts.</p><p class="src">Site, Instagram, ROC and the state's records</p></div>
      </div></div></section>
    ${APP.next("arrive", "How work arrives")}`;

  /* ---------- how work arrives ---------- */
  const DOORS = [
    ["users", "Builders", "The main door. Custom builders invite a short list of subs they trust, and a builder who likes you sends the next house without a bid war.", "Today: relationships and word of mouth", "radar"],
    ["est", "Architects and designers", "They decide where the slots go and who sees the plans first. One architect who trusts your design work is worth a dozen cold invites.", "Today: whoever already knows you", "projects"],
    ["pin", "Permits", "Every custom home in Scottsdale is on a public list with the builder's name, months before HVAC is bid. Almost no sub watches it.", "Today: not watched", "radar"],
    ["search", "Homeowners searching", "Remodels, casitas, replacements and July breakdowns. They search Google, ask Nextdoor, and check the SRP rebate list.", "Today: no Google listing, no reviews", "marketing"],
    ["repeat", "Your own installed base", "Every system you've set is a house that needs tune-ups, warranty calls and, one day, a replacement. The cheapest work you'll ever win.", "Today: no service plan offered", "service"],
  ];
  APP.views.arrive = () => head("How work arrives", "Five doors.<br>Only one has a sign on it.", "Work comes to an HVAC sub doing custom homes through five doors. Right now nearly all of it comes through one: people who already know you. Here's each door, what's behind it, and what the Mechanical Room does to open it.")
    + `<section class="sec" style="padding-top:20px"><div class="wrap"><div class="doors rise">${DOORS.map((d, i) => `<a class="door" href="#${d[4]}"><span class="dn">${String(i + 1).padStart(2, "0")}</span><span class="mi">${svgI(d[0], 22)}</span><b>${d[1]}</b><p>${d[2]}</p><small>${d[3]}</small></a>`).join("")}</div></div></section>`
    + `<section class="sec"><div class="wrap"><div class="kick">Door 1 · Builders</div><h2 class="h2 rise">Ten builders closed $320 million of custom homes in a year.</h2>
      <p class="lede rise">The Phoenix Business Journal ranks the Valley's largest custom builders by closings. Each builds a steady stream of houses, each house needs several systems, and each picks HVAC subs from a short list. Getting on two or three of these lists is a year of work.</p>
      ${tbl(["Builder", "2024 closings", "Most expensive home"], [["Cullum Homes", "$82.9M", "$7.0M"], ["Salcito Custom Homes", "$52.6M", "$13.7M"], ["A Finer Touch Construction", "$35.2M", "$19.3M"], ["Platinum Companies", "$29.7M", "$6.2M"], ["Fisher Custom Homes", "$26.0M", "$5.5M"], ["Sage Luxury Homes", "$24.0M", "$12.0M"], ["Travis Custom Homes", "$22.8M", "$9.8M"], ["Forté Homes", "$18.5M", "$6.8M"], ["Calvis Wyant Luxury Homes", "$16.5M", "$6.5M"], ["Boxwell Homes", "$12.5M", "$5.3M"]])}
      <p class="src">${src("Phoenix Business Journal list, via Real Estate Daily News", "https://realestatedaily-news.com/cullum-homes-tops-2024-list-of-largest-phoenix-area-custom-home-builders/")}. Salcito, Cullum and Boxwell also run remodel businesses ($12M, $9M and $4M). Forté and Starwood build in both Scottsdale and the East Valley, near your shop.</p>
      <div class="card rise" style="margin-top:24px;border-color:rgba(224,122,46,.45)"><b style="font-size:20px">One relationship, 29 houses</b><p class="mute" style="font-size:16px;margin:8px 0 0">Armstrong Construction Group is building 29 homes across Scottsdale and Paradise Valley, $5.8M to $6.4M each, 6,800 to 7,400 sq ft. Six were underway in February with 18 expected within the year. That's one bid relationship with recurring HVAC scope.</p><p class="src">${src("Scottsdale REALTORS / PBJ, Feb 2026", "https://www.scottsdalerealtors.org/2026/02/23/scottsdale-builder-to-develop-29-luxury-homes-across-scottsdale-and-paradise-valley/")}</p></div>
    </div></section>`
    + `<section class="sec"><div class="wrap"><div class="kick">Door 2 · Architects and designers</div><h2 class="h2 rise">Be in the room where the ceiling gets drawn.</h2>
      ${tbl(["Where they are", "What it is", "Cost to be there"], [["AIA Arizona, Allied member", "Puts a sub in the room with architects. Allied members hold a board seat", "From $462 a year"], ["ASID Arizona North", "About 500 interior designers and 207 industry partners", "About $470 a year, local"], ["HBACA, associate member", "The builders' association since 1951. A public member directory, luncheons, trade shows", "$1,000 a year, 1 to 10 employees"], ["Home tours", "Scottsdale Luxury Home Tour (April), Phoenix Home & Garden Home Tour (fall). The subs on those homes get seen", "Time, and photos of your work in those homes"]])}
      <p class="src">${src("AIA Arizona", "https://aia-arizona.org/?p=760")} · ${src("ASID Arizona North", "https://azn.asid.org/about/chapter-profile")} · ${src("HBACA membership", "https://www.hbaca.org/membership-overview/")} · ${src("Scottsdale REALTORS home tour", "https://www.scottsdalerealtors.org/?p=40257")}. We found no current Phoenix Parade of Homes, so it's not on this list.</p>
      <p class="lede rise" style="margin-top:24px">Your photos are the pitch: slots lined up with wood planks, returns you can't find. An architect sees that and knows you'll draw around their ceiling, not through it. The Mechanical Room keeps every architect and designer you've worked with, which houses they drew, and sends them the finished photos.</p>
    </div></section>`
    + `<section class="sec"><div class="wrap split" style="align-items:start">
      <div class="rise"><div class="kick">Door 3 · Permits</div><h2 class="h2">Know the house before the builder calls.</h2><p class="lede">Scottsdale publishes every single-family permit as a free download, with the <b>owner, the builder</b>, the address, the air-conditioned square footage and the valuation on each row. A custom home gets its permit months before mechanical rough-in. Whoever reads that list first gets to the superintendent first.</p>
        <p class="lede">In one stretch of May and June 2026, Scottsdale issued 79 residential permits worth $28.4M, including 9 guest houses: ductless jobs.</p><p class="src">${src("Scottsdale Building Permit Reports", "https://eservices.scottsdaleaz.gov/bldgresources/BuildingPermit/reports")} · the 79-permit count is ${src("a vendor's tally of the city's data", "https://ustechautomations.com/resources/blog/scottsdale-building-permit-report-june-2026")}, not the city's own</p></div>
      <div class="rise">${tbl(["City", "What's published"], [["Scottsdale", "Free CSV, 3 years at a time, builder on every row"], ["Phoenix (Arcadia)", "Issued-permit export and map data"], ["Mesa", "Building permits on the city's data hub"], ["Gilbert", "Weekly issued-permit reports, as PDFs"], ["Paradise Valley", "Per-permit lookup; bulk lists by records request"], ["Maricopa County", "Permit map for unincorporated areas"]])}<p class="src">research/market-and-bottlenecks.md, section A5</p></div>
    </div></section>`
    + `<section class="sec"><div class="wrap"><div class="kick">Door 4 · Homeowners</div><h2 class="h2 rise">The homeowner door is open. It just has no handle.</h2>
      <div class="grid g3 rise" style="margin-top:26px">
        <div class="card"><b style="font-size:20px">Google first</b><p class="mute" style="font-size:16px">There's no Google Business Profile today. Practitioners credit the profile and its reviews with about half of who shows up in the map. Paid Local Services leads run about $45 to $80 each in Phoenix, highest June to September.</p><p class="src">${src("Whitespark 2026 survey summary", "https://visionary-marketing.co.uk/blog/local-seo-ranking-factors-2026")} · ${src("agency pricing", "https://thevalleymarketinggroup.com/blog/google-local-service-ads-cost-per-lead-2026/")} (agencies sell these leads)</p></div>
        <div class="card"><b style="font-size:20px">SRP's contractor list</b><p class="mute" style="font-size:16px">SRP pays $75 to $225 per ton on a qualifying AC or heat pump, up to $1,125, for installs through April 30, 2027. Contractors sign SRP's terms, and SRP points customers to its list of participating contractors. A free lead source. The federal 25C credit ended in 2025.</p><p class="src">${src("SRP rebates", "https://srpnet.com/energy-savings-rebates/home/rebates/air-conditioner")} · ${src("SRP contractor terms", "https://www.srpnet.com/assets/srpnet/pdf/energy-savings-rebates/home/rebates/ac-rebate-contractor-terms.pdf")}</p></div>
        <div class="card"><b style="font-size:20px">Casitas and guest houses</b><p class="mute" style="font-size:16px">Luxury remodels keep adding casitas, gyms, wine rooms and garages. That's ductless work, and manufacturers' dealer locators send homeowners straight to listed contractors. Which brands you install decides which locator to get on.</p><p class="src">Inference from Scottsdale's guest-house permits. research/market-and-bottlenecks.md, section A3</p></div>
      </div></div></section>`
    + `<section class="sec"><div class="wrap split">
      <div class="rise"><div class="kick">Door 5 · Your installed base</div><h2 class="h2">500 systems is a service business.</h2><p class="lede">If the site's 500+ is right, that's hundreds of tune-ups a year you aren't booking yet. 72% of HVAC contractors offer maintenance agreements; in one survey 87% of homeowners said they'd pay $100 to $200 a year for one. Every custom home you finish should leave with the owner on a plan.</p><p class="src">${src("ACHR News survey", "https://achrnews.com/articles/153922-homeowners-contractors-mutually-support-maintenance-agreements")} · your home page</p></div>
      <div class="rise card"><b style="font-size:20px">And the calendar helps</b><p class="mute" style="font-size:16px">Phoenix had 70 days at 110°F or hotter in 2024, against a typical 21. Fall and winter are when owners plan replacements. A plan books February tune-ups before the phones ring in June.</p><p class="src">${src("KJZZ", "https://www.kjzz.org/kjzz-news/2025-01-01/2024-will-likely-be-confirmed-as-phoenixs-hottest-year-ever")} · ${src("SRP", "https://media.srpnet.com/cooler-months-are-ideal-time-to-plan-for-summer-heat/")}</p></div>
    </div></section>`
    + `<section class="sec"><div class="wrap"><div class="kick">How one house should flow</div><h2 class="h2 rise">From a permit to a service plan, without anyone retyping it.</h2>
      <div class="pill-row rise" style="margin-top:22px">${["Permit issued", "Builder matched", "Intro to the super", "Plans in", "Manual J, S, D", "Bid with an expiration", "Follow-ups day 3, 7, 14", "Won", "Job and budget", "Underground", "Rough-in", "Inspections", "Draws and notices", "Trim", "Start-up and balance", "Warranty registered", "Review requested", "Service plan", "Replacement, year 10+"].map((t, i, a) => `<span>${t}</span>${i < a.length - 1 ? `<span style="border:0;background:none;padding:7px 0;color:var(--race)">→</span>` : ""}`).join("")}</div>
    </div></section>`
    + APP.next("stuck", "Where it gets stuck");

  /* ---------- where it gets stuck ---------- */
  const STUCK = [
    ["Skylar is the estimating department", "Every custom-home bid is a plan read, Manual J, S and D, equipment, a duct layout, a takeoff and a proposal. Our estimate: 6 to 20 hours a bid. Subs win about 1 in 4 to 1 in 7, so each house you win carries 25 to 140 hours of unpaid bidding. And an architect's revision starts it over.", "Load calcs from the plan set, a price book of your own assemblies, a proposal in one click, and follow-ups at day 3, 7 and 14 with a win or loss reason.", "estimate", "1 in 4 to 7", "bids won"],
    ["July versus the builder's schedule", "Seventy days over 110°F in 2024. A small crew can't promise same-week service and hold a rough-in date when both land on one morning, and right now the only scheduler is Skylar's head.", "Installs and service on one board, a triage form for calls (no cool, weak cool, tune-up), and a next-open time the board works out, not a guess.", "schedule", "70 days", "at 110°F+, 2024"],
    ["Leads wait for a free hand", "One form, one phone, one inbox. Nothing answers a 9 p.m. no-cool call or confirms a builder's plan set came in. Paid leads in Phoenix cost $45 to $80 each, so a missed one is money.", "An instant text back to every form and missed call, booking links, leads sorted by builder, homeowner or service, and a review request after every job.", "phone", "$45 to $80", "per paid lead"],
    ["Coordinating with the builder", "Rough has to pass before insulation, and a failed inspection costs about a week. Drywall dates move by email. Change orders on architect-led homes leak margin when they're agreed on site and written up later.", "A milestone tracker per house, builder emails that file themselves and move the calendar, and change orders priced and signed on a phone before the work.", "auto", "48%", "of rework is miscommunication"],
    ["Getting paid", "The 20-day preliminary notice protects lien rights. On an owner-occupant's home, a sub hired by the builder may have no lien right at all. Direct homeowner jobs lose prompt-pay protection unless a notice is printed on every estimate and invoice. Retention is a second collection that gets forgotten.", "Notices drafted and mailed when a job starts, owner-occupied jobs flagged, the prompt-pay notice printed automatically, and day-8 interest reminders.", "money", "Day 8", "late interest starts, 1.5%/mo"],
    ["Equipment prices move after you bid", "A custom home is bid 6 to 12 months before equipment is bought. Trane, Lennox and Daikin raised prices 5 to 10% this year, and Carrier adds 8% at the end of 2026. R-454B refrigerant carried surcharges of up to 42% and was rationed in 2025.", "A price book synced to the supply house, an expiration and price clause on every quote, and an alert listing every open bid a price notice touches.", "estimate", "8%", "Carrier increase, end of 2026"],
    ["No early warning", "Builders find you by word of mouth, after they've already started asking around. The permit lists that name every builder go unread.", "The Builder radar reads permits weekly in Scottsdale, Phoenix and Mesa, matches the builder, and hands you an intro task while the house is at foundation.", "radar", "Months", "of head start per permit"],
    ["The installed base sits idle", "500+ systems and no maintenance plan, no warranty registry, no replacement reminders. Every one of those owners will call someone in July.", "Every house's equipment, serials and warranty in one record, February tune-up campaigns, plan renewals, and year-10 replacement flags with the SRP rebate filled in.", "service", "500+", "systems, no plan offered"],
  ];
  APP.views.stuck = () => head("Where it gets stuck", "Eight bottlenecks.<br>Ranked.", "This is our read from everything public about Original Mechanical, and from how firms like it run. You'll know better than we do which are real, which is why the interview asks about each one. But if the business feels like it all runs through one person, this is why.")
    + `<section class="sec" style="padding-top:20px"><div class="wrap"><div class="stk rise">${STUCK.map((s, i) => `<div class="stk-i"><div class="stk-n">${String(i + 1).padStart(2, "0")}</div><div><h3>${esc(s[0])}</h3><p class="mute">${esc(s[1])}</p><div class="stk-fix"><b>${svgI("check", 16)} The fix</b><span>${esc(s[2])}</span><a href="#${s[3]}">See it →</a></div></div><div class="stk-k"><b>${esc(s[4])}</b><small>${esc(s[5])}</small></div></div>`).join("")}</div>
      <p class="src">Bid hours are our estimate (no published figure exists). Win rates: ${src("ENR", "https://enr.com/articles/23952-bid-hit-ratios-provide-valuable-road-map")}, ${src("1Build", "https://1build.com/blog/construction-bidding-process")}. Rework: ${src("FMI and PlanGrid", "https://www.autodesk.com/blogs/construction/construction-disconnected-fmi-report/")}. Prices: ${src("ACHR News", "https://www.achrnews.com/articles/166517-hvac-price-increase-list-august-2026")}, ${src("Honeywell surcharge", "https://www.achrnews.com/articles/164475-honeywell-announces-42-surcharge-on-r-454b")}. Arizona law: ${src("A.R.S. 32-1183", "https://www.azleg.gov/ars/32/01183.htm")}, ${src("32-1188", "https://www.azleg.gov/ars/32/01188.htm")}, ${src("33-992.01", "https://www.azleg.gov/ars/33/00992-01.htm")}, ${src("33-1002", "https://www.azleg.gov/ars/33/01002.htm")}. Not legal advice.</p></div></section>`
    + `<section class="sec"><div class="wrap split">
      <div class="rise"><div class="kick">The math of bidding</div><p class="quote">Each house you win costs <em>25 to 140 hours</em> of bids.</p><p class="lede">6 to 20 hours a bid, times 4 to 7 bids per win. Cut a bid to 2 hours of checking and approving, and the same win costs 8 to 14. That's the difference between bidding at night and bidding between jobs.</p><p class="src">Our estimate, labeled as one. We'd like to check it against your real numbers.</p></div>
      <div class="rise card"><b style="font-size:20px">What it adds up to</b><ul class="lst"><li><b>One person</b> doing the bids, the schedule, the sales and the hardest installs</li><li><b>One inbox</b> for builders, architects, suppliers, the city and homeowners</li><li><b>No record</b> of which builders pay fast, which bids won, or which houses are due for service</li><li><b>No room to grow</b> without hiring an office manager or an estimator first</li></ul></div>
    </div></section>`
    + APP.next("hub", "The Mechanical Room");

  /* ---------- the Mechanical Room ---------- */
  APP.views.hub = sub => head("The Mechanical Room", "Your whole business.<br>One login.", "The Mechanical Room is the back office behind the new site. Every builder, house, plan, load calc, receipt, draw, service call and crew day lives in one place, linked to each other. It's built for how Original Mechanical works, not for every HVAC company in America.")
    + portal(sub || "today")
    + `<section class="sec" style="padding-top:30px"><div class="wrap"><div class="kick">Everything linked</div><h2 class="h2 rise">Nothing typed twice.</h2>
      <p class="lede rise">A permit names a builder. The builder sends plans. The plans become a load calc, then a bid, then a job with a budget and a schedule that follows the builder's. Receipts and hours land on it. Draws go out from it with the right notices. When it's started up, the equipment joins your installed base and the owner joins a service plan.</p>
    </div></section>`
    + cards("On every device.", [["phone", "The crew's phones", "Their day at 5:30 a.m., photos and voice notes to the job log, start-up checklists signed on site."], ["users", "Skylar's phone", "Approvals, new permits, leads, receipts that need a tap, and Ask Original for anything."], ["site", "The office", "The whole thing on a big screen: books, draws, schedules, load calcs and bids."]])
    + APP.next("schedule", "Daily calendar");

  APP.views.schedule = () => head("Daily calendar", "Builders and service calls.<br>One board.", "Installs, inspections, deliveries, service calls, tune-ups and builder deadlines on one calendar. Each house's timeline carries its budget, so you see a job slipping on time and money at the same moment, and a July service call can't quietly steal a rough-in.")
    + portal("schedule")
    + cards("How it ties together.", [["users", "Crews by house", "Drag a person onto a house and a day. They get the address, the mechanical sheet and the super's number. Their hours land on that job's labor."], ["cal", "Follows the builder", "When the builder's email moves drywall, rough-in, inspections and deliveries move with it, and the crew hears about it."], ["bolt", "Service without chaos", "Calls come in sorted by urgency. The board offers the first real opening, and plan members go first."]])
    + APP.next("projects", "Job files");

  APP.views.projects = () => head("Job files", "Every plan, revision, super and inspection.<br>One job file.", "Each house gets one place for the architect's drawings and the reflected ceiling plan, the load calc, rough-in photos, inspection results, the contract and change orders. The builder, super, architect and supply house are attached to it, and every email from them files itself there.")
    + portal("projects")
    + cards("How email files itself.", [["mail", "It knows who's on the house", "Kessler is the builder on Pinnacle Peak. An email from Kessler's super that says \"Pinnacle\" goes to Pinnacle Peak."], ["file", "It reads the attachments", "A new ceiling plan replaces the old one, with the slot changes marked. A schedule moves the calendar. A price notice flags the bids it touches."], ["camera", "Photos sort by house", "A photo taken at the address lands in that job, with the date, who took it, and what's in it."]])
    + APP.next("auto", "Auto-organization");

  /* ---------- auto-organization ---------- */
  APP.views.auto = () => head("Auto-organization", "The office<br>organizes itself.", "When a builder, architect, supply house or the city emails about a job, the Mechanical Room files the attachment, writes the note, puts the deadline on the calendar and hands the task to the right person. The crew gets texted, everyone gets their week, and nobody has to sort anything.")
    + portal("inbox")
    + cards("How it knows where things go.", [["users", "Who's on the house", "Every builder, super, architect and inspector is attached to the houses they're on. Their email starts on the right job before it's read."], ["pin", "What the email says", "Addresses, lot numbers, job names, PO numbers and permit numbers all point to one house. If two fit, it asks Skylar with one tap."], ["file", "What's inside", "Schedules move the calendar. Plan revisions replace the old sheets. Inspection results move the job forward. Price notices flag your open bids."]])
    + `<section class="sec" style="padding-top:30px"><div class="wrap"><div class="kick">The crew</div><h2 class="h2 rise">Everyone's number. Who's free. One tap.</h2><p class="lede rise">The whole crew in one list with their numbers, skills and where they are. Staffing a house: pick the people, ask who's free, and their YES or NO texts fill in the calendar. Texts come from the shop's own number.</p></div></section>`
    + portal("crew")
    + `<section class="sec" style="padding-top:20px"><div class="wrap split">
      <div class="rise"><div class="kick">Everyone knows where to be</div><h2 class="h2">Their week, in their inbox.</h2><p class="lede">Every Sunday at 6 p.m. each person gets their week: which house each day, the address, what to do, the mechanical sheet and which super to call. Every morning a text with the day. When a builder moves something, only the people it affects hear about it.</p></div>
      <div class="rise" style="display:grid;gap:14px;justify-items:center"><div style="width:min(340px,100%);background:#1a120c;border-radius:34px;padding:16px 14px 22px;border:1px solid var(--line2);box-shadow:0 30px 80px -30px #000"><div style="text-align:center;font-size:12px;color:#a8998a;margin-bottom:10px">Original Mechanical · Text Message · 5:30 AM</div>
        <div style="background:#3a2d22;color:#fff;border-radius:18px;border-bottom-left-radius:5px;padding:12px 14px;font-size:15px;line-height:1.4">Morning Marcus. Today: <b>Pinnacle Peak</b>. Rough inspection 7:30 with the city, then line sets for systems 3 and 4. Jake is with you. Gate code and M-101 in the app.</div>
        <div style="background:#b86a32;color:#fff;border-radius:18px;border-bottom-right-radius:5px;padding:10px 14px;font-size:15px;margin:10px 0 0 auto;width:fit-content">👍 on it</div>
        <div style="background:#3a2d22;color:#fff;border-radius:18px;border-bottom-left-radius:5px;padding:12px 14px;font-size:15px;line-height:1.4;margin-top:10px">Change: Kessler moved drywall to Monday. Chases close Friday. Skylar will meet you there at 2.</div></div><p class="src">Sample texts</p></div>
    </div></section>`
    + `<section class="sec" style="padding-top:10px"><div class="wrap"><div class="rise">${APP.staffEmail("Marcus Reyes")}</div><p class="src">A sample of the Sunday email, for Marcus.</p></div></section>`
    + `<section class="sec"><div class="wrap"><div class="kick">When a house is done</div><h2 class="h2 rise">Finishing runs itself too.</h2>
      <div class="grid g3 rise" style="margin-top:26px">${[["check", "Start-up checklist closes", "Static pressure, airflow, charge and controls, signed on site, and the balancing report goes to the builder."], ["repeat", "Into the installed base", "Model and serial numbers from the start-up photos, and the warranty registered the same week."], ["camera", "Photos to the website", "Skylar picks the best finished shots. They post to the site, Houzz and Instagram, with the builder and architect credited."], ["star", "Two review requests", "One to the owner, one to the builder, each a short text from Skylar with a Google link."], ["money", "Retention on the calendar", "The release date and the final waiver are set the day the final passes."], ["cal", "The owner on a plan", "A service plan offer, and the first tune-up booked for spring."]].map(c => `<div class="card"><span style="color:#f2a865">${svgI(c[0], 24)}</span><b style="font-size:19px;display:block;margin-top:8px">${c[1]}</b><p class="mute" style="font-size:15.5px;margin:6px 0 0">${c[2]}</p></div>`).join("")}</div></div></section>`
    + APP.next("estimate", "Load calcs and bids");

  /* ---------- load calcs and bids ---------- */
  APP.views.estimate = () => head("Load calcs and bids", "Plans in.<br>Load calc, layout and bid out.", "Drop in the architect's plan set. The Mechanical Room reads the rooms, windows and ceiling heights, runs Manual J, S and D, picks equipment, prices it from your own past houses and today's supply house prices, and makes the proposal. Nothing goes out without Skylar's OK.")
    + portal("estimate")
    + `<section class="sec" style="padding-top:20px"><div class="wrap split">
      <div class="rise"><div class="kick">The math</div><p class="quote">From <em>6 to 20 hours</em> a bid, to the time it takes to check one.</p><p class="lede">The counting and the code-required load math move to the system. What's left for you is the judgment: the equipment you trust, where the slots go, and what to charge this builder.</p><p class="src">Bid hours are our estimate. Manual J, S and D are the model code's sizing standard; we'll confirm with Mesa, Scottsdale and Phoenix plan review which reports they ask for.</p></div>
      <div class="rise card"><b style="font-size:20px">Built your way</b><ul class="lst"><li><b>Your price book.</b> Unit prices from your own receipts and hours on past houses, updated as each one closes</li><li><b>Your assemblies.</b> "Linear slot run with plenum" or "4-ton variable-speed system, attic air handler" with labor built in</li><li><b>Your equipment.</b> The brands and models you install, at today's supply house price</li><li><b>Your proposal,</b> with scope, exclusions, an expiration date and an equipment price clause</li><li><b>Bid vs. actual</b> on every finished house, so it gets sharper every time</li></ul></div>
    </div></section>`
    + cards("Price risk, handled.", [["bell", "Price notices read", "When a supply house emails an increase, every open bid and signed job it touches is listed, with what it costs you."], ["shield", "A clause on every quote", "Each proposal expires and carries an equipment price clause, so an 8% increase isn't yours to eat."], ["money", "Buy when it's cheaper", "For signed houses, it suggests ordering before the increase, and holds the equipment for the job."]])
    + `<section class="sec" style="padding-top:10px"><div class="wrap"><div class="card rise" style="border-color:rgba(230,199,160,.4)"><b style="font-size:20px">Being straight about it</b><p class="mute" style="font-size:16px;margin:8px 0 0">AI reading plans is good on clean drawings and needs a person to check it. Architects revise, and some rooms need a judgment call. So the Mechanical Room does the counting, the load math and the paperwork, and Skylar makes the calls. It saves the hours, not the expertise.</p></div></div></section>`
    + APP.next("radar", "Builder radar");

  /* ---------- builder radar ---------- */
  APP.views.radar = () => head("Builder radar", "Know the house<br>before the builder calls.", "The radar reads new permits every week in Scottsdale, Phoenix, Mesa and Gilbert, plus your bid invites. It scores each one for fit (size, area, builder, the kind of work you want), matches the builder to your records, and hands you the next move: an intro, a draft bid, or a pass.")
    + portal("bids")
    + `<section class="sec" style="padding-top:20px"><div class="wrap"><div class="kick">Where it looks</div><h2 class="h2 rise">The sources.</h2>
      ${tbl(["Source", "What's there", "How the radar reads it"], [["Scottsdale permit reports", "Every single-family permit with owner, builder, AC square footage and valuation", "Weekly download"], ["Phoenix permit data", "Issued permits, including Arcadia", "Data export and map service"], ["Mesa data hub", "Building permits, refreshed nightly", "Open data"], ["Gilbert", "Weekly issued-permit reports", "Reads the PDFs"], ["Paradise Valley", "Per-permit lookups", "Periodic records requests"], ["BuildingConnected", "Bid invites from GCs, mostly commercial", "Invite emails"], ["The builder list", "PBJ's top custom builders, the HBACA directory, every builder you've worked with", "Your records"]])}
      <p class="src">research/market-and-bottlenecks.md, sections A2 and A5. Scottsdale's is the best feed: free, with the builder's name on every row.</p></div></section>`
    + cards("What it does, and doesn't.", [["bid", "Finds and sorts", "Skips tract homes and jobs too far out, explains each score, and groups permits by builder so you see who's busy."], ["users", "Makes the intro easy", "Drafts a short note to the builder's super with photos of a similar house you did. You send it."], ["check", "Never sends on its own", "Every intro and every bid waits for you. It just puts the right house in front of you months early."]])
    + `<section style="padding:0 0 40px"><div class="wrap" style="max-width:1320px"><div class="rise">${APP.hub("subs")}</div><p class="src">Every builder's record: pay speed, bids won, and their next houses from the radar. Samples.</p></div></section>`
    + APP.next("service", "Installed base");

  /* ---------- installed base ---------- */
  APP.views.service = () => head("Installed base", "Every system you've set<br>is a service customer.", "Each finished house leaves with its equipment, serials, refrigerant, warranty and start-up readings on file, and its owner on a plan. Tune-ups book themselves before summer. Replacements get flagged before they fail. July calls go to plan members first.")
    + portal("reinspect")
    + `<section class="sec" style="padding-top:20px"><div class="wrap split">
      <div class="rise"><div class="kick">The numbers</div><p class="quote"><em>87%</em> of homeowners say they'd pay $100 to $200 a year for a plan.</p><p class="lede">72% of contractors offer one. In one industry survey, the most common answer was that 21 to 30% of appointments came from agreements. Original Mechanical doesn't offer one yet.</p><p class="src">${src("ACHR News", "https://achrnews.com/articles/153922-homeowners-contractors-mutually-support-maintenance-agreements")} · ${src("EGIA", "https://mycontractoruniversity.com/snapshot-survey-results-call-ins-vs-service-agreement-program/")}</p></div>
      <div class="rise card"><b style="font-size:20px">What a plan does for you</b><ul class="lst"><li>Spring and fall visits you schedule in the slow months</li><li>Money that arrives every year, not just when a house is built</li><li>The owner calls you, not a stranger, when something breaks</li><li>The replacement in year 10 or 12 is yours, with the SRP rebate filled in</li></ul></div>
    </div></section>`
    + cards("Service, built in.", [["bolt", "Calls sorted by urgency", "No cool, weak cool, noise, tune-up. Plan members and builders' warranty calls first."], ["phone", "Text back in seconds", "Every call and form gets a reply with the first real opening, at any hour."], ["shield", "Warranty, never lost", "Registration done the week of install, from the start-up photos. Claims start from the house's record."]])
    + APP.next("money", "Draws and paperwork");

  /* ---------- money ---------- */
  APP.views.money = () => head("Draws and paperwork", "Every dollar on the right house.", "Receipts match themselves to jobs. Draws go out in the format each builder pays from, with the waiver and the inspection attached. Arizona's notices and deadlines are drafted and on the calendar. And if you want, the Mechanical Room keeps the books itself.")
    + portal("receipts")
    + `<section class="sec" style="padding-top:10px"><div class="wrap"><div class="rise">${APP.hub("billing")}</div></div></section>`
    + `<section class="sec" style="padding-top:10px"><div class="wrap"><div class="rise">${APP.hub("paperwork")}</div></div></section>`
    + `<section class="sec" style="padding-top:10px"><div class="wrap"><div class="kick">The deadlines it keeps</div><h2 class="h2 rise">Arizona, handled.</h2>
      ${tbl(["What", "The rule"], [["Preliminary notice", "Within 20 days of first furnishing, to the owner, the builder, the lender and whoever hired you. A new one if the price rises 30% or more"], ["Owner-occupied homes", "On a home the owner held title to before work began, only someone with a written contract directly with the owner can lien"], ["Builder pays the sub", "Within 7 days of being paid, retention included. Interest of 1.5% a month starts on day 8"], ["Homeowner-direct jobs", "Prompt-pay protection applies only if the statutory notice is printed on the front of every estimate and billing"], ["Owner billings", "Approved after 14 days unless the owner objects in writing; paid within 7 days of approval"], ["Lien deadline", "120 days after completion, or 60 after a notice of completion"]])}
      <p class="src">${src("A.R.S. 33-992.01", "https://www.azleg.gov/ars/33/00992-01.htm")} · ${src("33-1002", "https://www.azleg.gov/ars/33/01002.htm")} · ${src("32-1182", "https://www.azleg.gov/ars/32/01182.htm")} · ${src("32-1183", "https://www.azleg.gov/ars/32/01183.htm")} · ${src("32-1188", "https://www.azleg.gov/ars/32/01188.htm")}. Not legal advice; your attorney sets the forms.</p></div></section>`
    + `<section class="sec" style="padding-top:10px"><div class="wrap"><div class="rise">${APP.hub("books")}</div></div></section>`
    + cards("The choices are yours.", [["book", "Keep QuickBooks, or replace it", "Either the Mechanical Room feeds QuickBooks with everything coded by job, or it keeps the books itself and your CPA gets a clean export."], ["users", "Your payroll company", "We'll connect to whoever runs payroll now, or run it here. That's a question for the interview."], ["camera", "The field, too", "Daily logs and voice notes, start-up checklists and refrigerant logs, from the crew's phones to the job."]])
    + APP.next("marketing", "Listings and reviews");

  APP.views.marketing = () => head("Listings and reviews", "Found everywhere.<br>Matching everywhere.", "One profile in the Mechanical Room feeds the website, Google, Houzz, the SRP list, the HBACA directory, Instagram and Yelp. Every finished house asks for a review. Every lead shows which door it came through.")
