  APP.views.phone = () => head("From your phone", "Run the shop<br>from the truck.", "The Mechanical Room has its own phone number. Text it like you'd text a good office manager: a photo of a receipt, a question, a yes. And if you use ChatGPT, connect it and ask anything about the business in plain English.")
